public class Stats {
    static double average(int[] values) {
        double total = 0;
        for (int x : values) total += x;
        return total / values.length;
    }

    public static double variance(int[] xs) {
        double m = average(xs);
        double sq = 0;
        for (int x : xs) sq += (x - m) * (x - m);
        return sq / xs.length;
    }

    public static double stdDev(int[] xs) {
        return Math.sqrt(variance(xs));
    }
}

